dslRule:
/*!
@id: org.eclipse.jface.text.refactor-enable-colored-labels
@description: Replace direct assignment to 'fIsColoredLabelsSupportEnabled' with a delegated call to 'fAssistant.enableColoredLabels()'.
@severity: HINT
*/
fIsColoredLabelsSupportEnabled = $value$;
=>
fAssistant.enableColoredLabels($value$);
;;

beforeExample:
import org.eclipse.jface.text.link.ContentAssistant;

class LinkedModeUI {
    private boolean fIsColoredLabelsSupportEnabled = false;
    private ContentAssistant fAssistant = new ContentAssistant();

    public void enableColoredLabels(boolean isEnabled) {
        fIsColoredLabelsSupportEnabled = isEnabled;
    }
}

afterExample:
import org.eclipse.jface.text.link.ContentAssistant;

class LinkedModeUI {
    private boolean fIsColoredLabelsSupportEnabled = false;
    private ContentAssistant fAssistant = new ContentAssistant();

    public void enableColoredLabels(boolean isEnabled) {
        fAssistant.enableColoredLabels(isEnabled);
    }
}

negativeExample:
